// Este script tienen todos los poligonos de remapeo
// Toma la clasificación que tiene el primer filtro espacial y los temporales
// Aplica remap para correccion de clases en base a poligonos, y la correccion de sombras por pendiente
// Exporta clasif final, insumo del último filtro espacial

var image = ee.Image('projects/mapbiomas-argentina/assets/LAND-COVER/COLLECTION-2/GENERAL/CLASSIFICATION/FILTERS/CUYO/CUYO-FINAL-2-1sp-T3y-4y-5y-12y3Ext')

var year = 2010


var zonif = ee.FeatureCollection('projects/mapbiomas-argentina/assets/ANCILLARY_DATA/VECTOR/CUYO/regional-assets_cuyo-argcol2_buffer2km_reg')

var DEM = ee.Image("NASA/NASADEM_HGT/001").select("elevation")
var slope =  ee.Terrain.slope(DEM).clip(zonif).rename("slope")
//Map.addLayer(slope)



// Mosaicos Landsat
var mosaics = ee.ImageCollection('projects/nexgenmap/MapBiomas2/LANDSAT/ARGENTINA/mosaics-1');

var years = [
    1985, 1986, 1987, 1988, 1989, 
    1990, 1991, 1992, 1993, 1994, 
    1995, 1996, 1997, 1998, 1999, 
    2000, 2001, 2002, 2003, 2004, 
    2005, 2006, 2007, 2008, 2009, 
    2010, 2011, 2012, 2013, 2014, 
    2015, 2016, 2017, 2018, 2019, 
    2020, 2021, 2022, 2023, 2024
];

// Visualización personalizada
var visMos = {
  min: 9000,
  max: 12000,
  palette: ['white', 'black']
};


// Lista para acumular las imágenes por año
var bandList = years.map(function (year) {
  var image = mosaics
    .filter(ee.Filter.eq('year', year))
    .filterBounds(zonif.filter(ee.Filter.eq('Id', 5)))
    .select('evi2_median')
    .mosaic()
    .rename(year.toString()); // renombrar la banda con el año

  return image;
});



// Convertir lista de imágenes a ee.Image y concatenar como bandas
var evi2_median = ee.ImageCollection.fromImages(bandList).toBands();


// Visualización personalizada
