var mask = imagen_corregida.eq(21).clip(MosaicoToLeniosaCult);
var correccion = imagen_corregida.where(mask, 9);
var imagen_corregida = imagen_corregida.blend(correccion);

////HumedalToArbustalAbierto
////// Cambia los pixeles con valor 11 dentro de la geometría a 77 en todas las bandas
var mask = imagen_corregida.eq(11).clip(HumedalToArbustalAbierto);
var correccion = imagen_corregida.where(mask, 77);
var imagen_corregida = imagen_corregida.blend(correccion);

////LeniosaCultToHumedal
////// Cambia los pixeles con valor 9 dentro de la geometría a 11 en todas las bandas
var mask = imagen_corregida.eq(9).clip(LeniosaCultToHumedal);
var correccion = imagen_corregida.where(mask, 11);
var imagen_corregida = imagen_corregida.blend(correccion);

////LeniosaCultToMosaico
////// Cambia los pixeles con valor 9 dentro de la geometría a 21 en todas las bandas
var mask = imagen_corregida.eq(9).clip(LeniosaCultToMosaico);
var correccion = imagen_corregida.where(mask, 21);
var imagen_corregida = imagen_corregida.blend(correccion);

////BosqueCerradoToLeniosaCult 
////// Cambia los pixeles con valor 3 dentro de la geometría a 9 en todas las bandas
var mask = imagen_corregida.eq(3).clip(BosqueCerradoToLeniosaCult);
var correccion = imagen_corregida.where(mask, 9);
var imagen_corregida = imagen_corregida.blend(correccion);

////BosqueAbiertoToMosaico 
////// Cambia los pixeles con valor 4 dentro de la geometría a 21 en todas las bandas
var mask = imagen_corregida.eq(4).clip(BosqueAbiertoToMosaico);
var correccion = imagen_corregida.where(mask, 21);
var imagen_corregida = imagen_corregida.blend(correccion);

////HumedalToSD
////// Cambia los pixeles con valor 11 dentro de la geometría a 25 en todas las bandas
var mask = imagen_corregida.eq(11).clip(HumedalToSD);
var correccion = imagen_corregida.where(mask, 25);
var imagen_corregida = imagen_corregida.blend(correccion);

//AguaToNoObservado (where slope > 10)
var mask = imagen_corregida.eq(33).mask(slope.gt(10)).clip(zonif.filter(ee.Filter.lte('Id', 5)));
var correccion = imagen_corregida.where(mask, 27)
var imagen_corregida = imagen_corregida.blend(correccion);

////HumedalToHerbacea (where region = 5 y EVI2_median < 12000)
var mask = imagen_corregida.eq(11).clip(zonif.filter(ee.Filter.eq('Id', 5)));
var correccion = imagen_corregida
  .where(mask.and(evi2_median.lte(12000)), 12)
  .where(mask.and(evi2_median.gt(12000)), 11)
var sinDatos = mask.and(evi2_median.mask().not());
correccion = correccion.where(sinDatos, 27);
var imagen_corregida = imagen_corregida.blend(correccion);


// Muestra la imagen corregida en la consola
//print("Imagen corregida:", imagen_corregida);



Map.addLayer(zonif.style({fillColor:"ff000000"}),null, 'regiones')
Map.addLayer(image.select('classification_' + year).clip(zonif), visClass, "original", false)
Map.addLayer(imagen_corregida.select('classification_' + year).clip(zonif), visClass, "corregida")//, false)
Map.setOptions("SATELLITE")

Map.addLayer(image.clip(zonif), null, "image", false)
Map.addLayer(imagen_corregida.clip(zonif), null, "imagecorregida", false)



var assetClass = 'projects/mapbiomas-argentina/assets/LAND-COVER/COLLECTION-2/GENERAL/CLASSIFICATION/FILTERS/CUYO';

Export.image.toAsset({
    "image": imagen_corregida,
    "description": 'CUYO-FINAL-2-1sp-T3y-4y-5y-12y3Ext-remap',
    "assetId": assetClass + '/CUYO-FINAL-2-1sp-T3y-4y-5y-12y3Ext-remap',
    "scale": 30,
    "pyramidingPolicy": {
        '.default': 'mode'
    },
    "maxPixels": 1e13,
    "region": zonif
}); 



//////////////////////LEYENDA///////////////////////////////
